// Making a request to the OpenAI API using an API Key

const OPENAI_API_KEY = process.env.OPENAI_SECRET_KEY; // Loaded securely from backend .env

fetch('https://api.openai.com/v1/chat/completions', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    // The API Key is passed via the Authorization header using 'Bearer'
    'Authorization': `Bearer ${OPENAI_API_KEY}`
  },
  body: JSON.stringify({ 
    model: "gpt-4", 
    messages: [{ role: "user", content: "Say hi" }] 
  })
});
